window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"87iCbMuugfU","speaker":"Nasry Juan Asfura Zablah","role":"President","country":"Honduras","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=87iCbMuugfU","date":"20260924","title":"🇭🇳 Honduras - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":886,"words":1550,"counts":{"claims":27,"promises":3,"attacks":0},"topics":[{"topic":"Honduras sovereignty","share":0.205,"seconds":182},{"topic":"Honduras economy","share":0.152,"seconds":135},{"topic":"Honduras mining","share":0.0793,"seconds":70},{"topic":"Climate change","share":0.0745,"seconds":66},{"topic":"Honduras security","share":0.0716,"seconds":63},{"topic":"Honduras elections","share":0.0715,"seconds":63},{"topic":"Honduras investment","share":0.0711,"seconds":63},{"topic":"Honduras energy","share":0.0698,"seconds":62},{"topic":"Honduras climate","share":0.0689,"seconds":61},{"topic":"Honduras infrastructure","share":0.0684,"seconds":61},{"topic":"Honduras agriculture","share":0.068,"seconds":60}],"timeline":[[2,71,"Honduras sovereignty"],[73,136,"Honduras elections"],[137,198,"Honduras economy"],[200,260,"Honduras sovereignty"],[261,324,"Honduras security"],[326,392,"Climate change"],[393,454,"Honduras climate"],[456,529,"Honduras economy"],[530,591,"Honduras infrastructure"],[593,654,"Honduras energy"],[656,716,"Honduras agriculture"],[717,787,"Honduras mining"],[789,852,"Honduras investment"],[853,905,"Honduras sovereignty"]],"stances":{"Honduras sovereignty":"Nasry Juan Asfura Zablah states that Honduras is a founding nation and one of the 50 countries that signed the agreement in San Francisco 81 years ago.","Honduras elections":"Nasry Juan Asfura Zablah states that Honduras' democracy was saved by institutions and the people through flawless elections despite a challenging context.","Honduras economy":"Nasry Juan Asfura Zablah states that his administration is reducing expenditure to invest in key sectors while maintaining macroeconomic stability and fiscal responsibility despite global economic challenges.","Honduras security":"Nasry Juan Asfura Zablah states that Honduras is strengthening its police and armed forces to combat transnational organized crime through shared responsibility.","Climate change":"Nasry Juan Asfura Zablah states that natural phenomena like drought and hurricanes share a root cause in climate extremes and require unified action.","Honduras climate":"Nasry Juan Asfura Zablah states that Honduras is actively preparing to mitigate climate change effects and investing resources to protect lives, harvests, and water access while inviting international solutions.","Honduras infrastructure":"Nasry Juan Asfura Zablah states that Honduras is optimizing the Puerto Cortez port and investing in road infrastructure to create a logistics corridor connecting the Atlantic and Pacific oceans.","Honduras energy":"Nasry Juan Asfura Zablah states that the National Congress adopted a reform to the electrical energy law to ensure stable and competitive energy prices for industries, inviting investment in the sector.","Honduras agriculture":"Nasry Juan Asfura Zablah states that coffee, agriculture, fisheries, and poultry are fundamental pillars for economic development and food security in Honduras.","Honduras mining":"Nasry Juan Asfura Zablah states that Honduras has the opportunity to develop a modern, responsible, and sustainable mining industry to create employment and transform resources into development and prosperity.","Honduras investment":"Nasry Juan Asfura Zablah expresses a commitment to facilitating investment in Honduras to create jobs and train the population."},"claims":[{"t":62,"quote":"one of the 50 countries who 81 years ago signed the agreement in San Francisco, California","topic":"Honduras sovereignty","kind":"fact"},{"t":78,"quote":"Nine months ago, the country went to the polls. Our democracy and freedom were in peril.","topic":"Honduras elections","kind":"fact"},{"t":102,"quote":"international observers bore witness to elections that were flawless in terms of their conduct.","topic":"Honduras elections","kind":"fact"},{"t":137,"quote":"Today, we are strengthening our and our multi-party democracy. Mr. since the very first day in office, we decided to govern differently with deeds.","topic":"Honduras economy","kind":"fact"},{"t":155,"quote":"We are reducing expenditure so that we can invest in health care, education, infrastructure, and security.","topic":"Honduras economy","kind":"fact"},{"t":164,"quote":"We're doing all of that whilst guaranteeing macroeconomic stability and with and guaranteeing a great deal of fiscal responsibility.","topic":"Honduras economy","kind":"fact"},{"t":200,"quote":"This is the only forum in which the voice of a country of 11 million inhabitants is heard.","topic":"Honduras sovereignty","kind":"fact"},{"t":258,"quote":"I visited Ukraine three months ago.","topic":"Honduras sovereignty","kind":"fact"},{"t":296,"quote":"We are equipping and strengthening our national police force and our armed forces.","topic":"Honduras security","kind":"fact"},{"t":310,"quote":"Drug trafficking networks and gangs operate in several countries at the same time","topic":"Honduras security","kind":"fact"},{"t":355,"quote":"Today, we are weathering a severe drought and we are taking tangible decisions to support our most vulnerable citizens.","topic":"Climate change","kind":"fact"},{"t":368,"quote":"The hurricanes that have beset us in the past and today's drought have the same root cause. That is a climate which is operating at increasing extremes","topic":"Climate change","kind":"fact"},{"t":394,"quote":"We are taking action by preparing as best we can to mitigate the effects of climate change. We are investing our own resources in protecting lives, harvests, and access to drinking water.","topic":"Honduras climate","kind":"fact"},{"t":414,"quote":"Honduras is opening its doors to anyone developing new solutions for water, agriculture, early warning, and the infrastructure that our country","topic":"Honduras climate","kind":"fact"},{"t":461,"quote":"In the seven months that my country has been in office, we have increased our international reserves to the tune of $1.3 billion","topic":"Honduras economy","kind":"number"},{"t":476,"quote":"We returned to the International Center of Arbitration SE on the 6th of March We'd been members of that center since 1989","topic":"Honduras economy","kind":"fact"},{"t":534,"quote":"We are optimizing Puerto Cortez. That is a port in our Caribbean Atlantic area and it is the port with greatest potential for growth in the country and one of the largest most important ports in Central America.","topic":"Honduras infrastructure","kind":"fact"},{"t":574,"quote":"Honduras is one of the world's key textile exporters. We manufacture the clothes of well-known brands. We also manufacture cable harnesses and automobile parts that are sold around the world.","topic":"Honduras infrastructure","kind":"fact"},{"t":596,"quote":"Around 200,000 Honduran people work in those industries.","topic":"Honduras energy","kind":"number"},{"t":616,"quote":"The National Congress recently adopted a reform to our electrical energy law.","topic":"Honduras energy","kind":"fact"},{"t":647,"quote":"We are the largest coffee exporter in Central America and the fifth largest globally.","topic":"Honduras energy","kind":"fact"},{"t":656,"quote":"50% 57% of the coffee which Honduras exports is caf coffee recognized to be of extremely high quality as well as accredited and specialized coffee","topic":"Honduras agriculture","kind":"number"},{"t":677,"quote":"sees its agriculture, fisheries and poultry industries as fundamental pillars for economic development as well as for food security and job creation","topic":"Honduras agriculture","kind":"fact"},{"t":765,"quote":"We have crystal clear waters and reefs in the Bay We have the great cup and ruins and the legacy of the Mayan civilization.","topic":"Honduras mining","kind":"fact"},{"t":797,"quote":"A young, hardworking and capable population.","topic":"Honduras investment","kind":"fact"},{"t":833,"quote":"Honduras is in a period of renewal. It has once again begun to believe in its institutions.","topic":"Honduras investment","kind":"fact"},{"t":862,"quote":"Our country has understood that sovereignty does not mean isolation. Rather, it means the ability to establish bonds with the rest of the world on the basis of equality","topic":"Honduras sovereignty","kind":"fact"}],"promises":[{"t":447,"quote":"Anyone who invests in Honduras will be offered opportunities, order, transparency, and clear rules.","topic":"Honduras climate","kind":"promise"},{"t":690,"quote":"Our commitment is to breathe momentum into these sectors sustainably","topic":"Honduras agriculture","kind":"promise"},{"t":826,"quote":"My commitment is to facilitate investment in Honduras.","topic":"Honduras investment","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"Honduras sovereignty","text":"The assembly will hear an address by his Nastri Yuan Asura Sabla, President of the Republic of Honduras. I request protocol to escort his excellency and invite him to address the A good evening to you all. May God bless you all. Your and your family. May you all enjoy great health. President of the General Assembly, Secretary General, Your Excellencies, Heads of State and distinguished delegates, is coming to this assembly today with the title of a founding nation, one of the 50 countries who 81 years ago signed the agreement in San Francisco, California."},{"t":73,"topic":"Honduras elections","text":"That was the United Nations Charter, the charter that today governs our work. Nine months ago, the country went to the polls. Our democracy and freedom were in peril. They were saved by the institutions that resisted and the Honduran people that decided at the polls with their vote decided to change the course of the country. And we, it's not just us saying that international observers bore witness to elections that were flawless in terms of their conduct. Flawless despite the challenging context. This was an effort waged by brave men and women. And we also enjoyed the support of international democracies who accompanied us in our attempts to rescue and restore our country's greatness. As we began our work, we found ourselves faced with a people who never lost their dignity, neither did they lose hope."},{"t":137,"topic":"Honduras economy","text":"Today, we are strengthening our and our multi-party democracy. Mr. since the very first day in office, we decided to govern differently with deeds. We are reducing expenditure so that we can invest in health care, education, infrastructure, and security. We're doing all of that whilst guaranteeing macroeconomic stability and with and guaranteeing a great deal of fiscal responsibility. No national effort alone can suffice in view of the global conditions that today determine the development of our Today the global economy is facing an energy crisis resulting from the high prices of oil. That crisis is having a direct impact on our people."},{"t":200,"topic":"Honduras sovereignty","text":"This is the only forum in which the voice of a country of 11 million inhabitants is heard. Honduras exercises sovereignty over the full extent of its national territory. Moreover, it administers its natural resources in accordance with its constitution. The law applies to each and every individual in all four country corners of the country because without legal security and certainty and without respect for private property there can be no peace, development, employment or investment. The right to development is something that it is the duty of the country's government to ensure for the millions of Honduran people. Honduras makes good on its promises. It honors its agreements and its treaties treaties. These principles are neither selective nor biased. I visited Ukraine three months ago."},{"t":261,"topic":"Honduras security","text":"There I saw a people defending its freedom and fighting for it in full respect of its territorial integrity and its political independence. I saw a country protecting civilians and working to achieve a lasting peace. Security cannot be imposed by decree. It is something that is built with resources, with training, and with political resolve. Today, that is exactly what we're doing. We are equipping and strengthening our national police force and our armed forces. We're doing this because transnational organized crime does not respect Drug trafficking networks and gangs operate in several countries at the same time and no country can vanquish them It is a matter of shared responsibility."},{"t":326,"topic":"Climate change","text":"Every nation must do its part. Democracies whose interests are aligned must unite and act together quickly and with resolve. It is only in so doing that we will enjoy security and prosperity in our hemisphere. Mr. President, there is another challenge that no country can face alone. Natural phenomena. Today, we are weathering a severe drought and we are taking tangible decisions to support our most vulnerable citizens. The hurricanes that have beset us in the past and today's drought have the same root cause. That is a climate which is operating at increasing extremes and that will affect the entire world for Our response is not simply to react to these disasters."},{"t":393,"topic":"Honduras climate","text":"Rather, we are taking action by preparing as best we can to mitigate the effects of climate change. We are investing our own resources in protecting lives, harvests, and access to drinking water. However, we want to go further. Honduras is opening its doors to anyone developing new solutions for water, agriculture, early warning, and the infrastructure that our country Addressing these challenges is allowing us to focus on the future. Honduras is a conscientious country, a country of law, a country in which we invite you to Anyone who invests in Honduras will be offered opportunities, order, transparency, and clear rules."},{"t":456,"topic":"Honduras economy","text":"We are adearing to the International Monetary Fund guidelines. In the seven months that my country has been in office, we have increased our international reserves to the tune of $1.3 billion and that is an increase of We returned to the International Center of Arbitration SE on the 6th of March We'd been members of that center since 1989 and we returned to resolve our problems with a sense of solemn With these steps, we sought to reiterate that in Honduras, rules apply to everyone and rules are followed. On that basis, Honduras can offer concrete investment opportunities in logistics, industry, energy, infrastructure, mining, tourism to name just a few We are the center of America."},{"t":530,"topic":"Honduras infrastructure","text":"We stand between two oceans. We are optimizing Puerto Cortez. That is a port in our Caribbean Atlantic area and it is the port with greatest potential for growth in the country and one of the largest most important ports in Central America. We are investing to strengthen our road infrastructure so that we can create a logistics corridor to join the Atlantic with the Pacific. This project and its location means that we can offer to the world safe, reliable, and efficient supply chains. Honduras is one of the world's key textile exporters. We manufacture the clothes of well-known brands. We also manufacture cable harnesses and automobile parts that are sold around the world."},{"t":593,"topic":"Honduras energy","text":"They've come from Honduran factories. Around 200,000 Honduran people work in those industries. These factories, mackilas, and other forms of industry require stable energy at competitive prices. It is for that reason that the National Congress recently adopted a reform to our electrical energy law. That reform had been championed by the presidency. In light of the above, we invite both national and foreign investment. Investment in the development of Honduras's energy sector. investment in the generation, transmission and distribution of energy. Our land is fertile land. We are the largest coffee exporter in Central America and the fifth largest globally."},{"t":656,"topic":"Honduras agriculture","text":"50% 57% of the coffee which Honduras exports is caf coffee recognized to be of extremely high quality as well as accredited and specialized coffee that is a reflection of the quality of our production and its standard of excellence. sees its agriculture, fisheries and poultry industries as fundamental pillars for economic development as well as for food security and job creation. Our commitment is to breathe momentum into these sectors sustainably. We want to empower our producers and bring high quality Honduran products to international Our land harbors mineral wealth with vast potential that has yet to be harnessed."},{"t":717,"topic":"Honduras mining","text":"We have the opportunity to develop a modern, responsible and sustainable mining industry so that we can create employment and transform these resources into development and prosperity for our We want to develop these resources with clear rules in full respect of the environment and for the benefit of our communities. Our extraordinary natural riches and cultural heritage make us a country with a vast wealth of potential for tourism. We have crystal clear waters and reefs in the Bay We have the great cup and ruins and the legacy of the Mayan civilization. And all of these things mean that we offer the world a unique combination of nature, history, and culture."},{"t":789,"topic":"Honduras investment","text":"And above all, we have the most valuable asset that any nation can hold. A young, hardworking and capable population. A population who demands and quite rightly so the opportunity to use their talent on their own in their own country. We want to see investment. We want investment to arrive in the country and to stay. We want investment that creates jobs and which brings knowledge to the table to train our young people. My commitment is to facilitate investment in Honduras. Honduras is in a period of renewal. It has once again begun to believe in its institutions. It is looking its allies straight in the face with pride and is working to build its future with a hardworking spirit and it wants to see a future of order and hope."},{"t":853,"topic":"Honduras sovereignty","text":"Honduras reaffirms its commitment to peace, international law, sovereignty and cooperation between states. Our country has understood that sovereignty does not mean isolation. Rather, it means the ability to establish bonds with the rest of the world on the basis of equality and May God bless you. May God bless your nations and may God bless Honduras. Many thanks to you all. &gt;&gt; On behalf of the assembly, I wish to thank the President of the Republic of Honduras."}],"compare":[{"topic":"Honduras","share":0.2766,"mean":0.0,"rank":1,"others":0},{"topic":"Climate Change","share":0.0745,"mean":0.0426,"rank":49,"others":77}]};
